var lastFlipTime = 0; // 记录上次翻页的时间

function handleTouch(e) {
    // 避免点到链接、按钮
    if (e.target && (e.target.tagName === 'A' || e.target.tagName === 'BUTTON' || e.target.tagName === 'INPUT')) {
        return;
    }

    // 核心防连击：500毫秒内只响应一次
    var now = new Date().getTime();
    if (now - lastFlipTime < 500) {
        if (e.type === 'touchend') e.preventDefault(); // 强行阻止多余的click
        return; 
    }

    var touch = e.changedTouches ? e.changedTouches[0] : e;
    var x = touch.clientX;
    var w = window.innerWidth;
    var h = window.innerHeight;

    // 🛠️ 改动1：滚动屏幕高度的 95%，比原来多看一点
    var scrollAmount = Math.floor(h * 0.95);

    // 阻止默认行为（防止Kindle自带滑动或App菜单干扰）
    if (e.type === 'touchend') {
        e.preventDefault();
        e.stopPropagation();
    }

    // 左半屏上翻，右半屏下翻
    if (x < w * 0.5) {
        window.scrollBy(0, -scrollAmount); 
    } else {
        window.scrollBy(0, scrollAmount);  
    }

    lastFlipTime = now; // 记录本次翻页时间
}

// 🛠️ 改动2：优先监听触摸事件，兼容老设备
if ('ontouchstart' in window) {
    document.body.addEventListener('touchend', handleTouch, true); 
} else {
    document.body.addEventListener('click', handleTouch, true);
}
